"use strict";
const memoryCommunities=[
 {id:'tianya',name:'天涯客厅',since:1999,url:'www.tianya.cn',tone:'tianya',intro:'海内存知己，天涯若比邻。',boards:['天涯杂谈','情感天地','煮酒论史'],topics:['十年以后，你还会记得这个夏天吗','下班路上，陌生人递给我一把伞','把家乡最好吃的小店留在这里']},
 {id:'mop',name:'猫扑大杂烩',since:1997,url:'www.mop.com',tone:'mop',intro:'灌一瓢水，等一位老朋友。',boards:['大杂烩','贴图区','灌水乐园'],topics:['来晒晒你的第一部手机，楼下接力','一人一句，写一部停不下来的故事','今天的快乐：五毛钱的冰棒和放学铃']},
 {id:'tieba',name:'贴吧小站',since:2003,url:'tieba.baidu.com',tone:'tieba',intro:'因为同一个喜欢，在同一层相遇。',boards:['校园吧','音乐吧','游戏吧'],topics:['【签到楼】晚自习结束的朋友进来坐坐','【求歌】旋律记得，名字忘了','【攻略】贪吃蛇绕圈，怎么才能不撞自己']},
 {id:'home',name:'QQ 家园街角',since:2003,url:'3g.qq.com',tone:'home',intro:'挂着家园，等菜长大，也等你回来。',boards:['家园日记','邻居留言','掌中游戏'],topics:['今天的小菜园又可以收获了','家园门牌换好了，欢迎邻居串门','半夜还在线的人，留一句晚安']},
 {id:'qzone',name:'空间留言板',since:2005,url:'qzone.qq.com',tone:'qzone',intro:'踩踩你的空间，留下一点心情。',boards:['我的日志','留言板','心情随笔'],topics:['把这首歌留在空间，等你来听','今天不写作业，写一段心情','请在这里留下你喜欢的那句话']},
 {id:'douban',name:'豆瓣小组角落',since:2005,url:'www.douban.com',tone:'douban',intro:'看过的电影，读过的书，说给懂的人听。',boards:['书与电影','生活小组','音乐交流'],topics:['哪一本书，陪你度过了很难的晚上','交换一张写着好天气的明信片','慢一点生活，从认真吃一顿晚饭开始']},
 {id:'xiaonei',name:'校内同学录',since:2005,url:'www.xiaonei.com',tone:'xiaonei',intro:'找到同学，翻翻照片，约好下一次见。',boards:['班级公告','相册回忆','新鲜事'],topics:['毕业合照里，你站在第几排','找人：当年坐我后桌的同学','周末回学校打球，还有人一起吗']},
 {id:'pengyou',name:'朋友网街区',since:2011,url:'www.pengyou.com',tone:'pengyou',intro:'那些认识的人，和那些想重新认识的人。',boards:['朋友动态','同学圈','周末约定'],topics:['好久不见，最近还好吗','以前的手机里，藏着多少老照片','找个周末，把那顿饭补上']}
];
let communityId='tianya',communityThread=null,communityReplies={};
try{const p=JSON.parse(localStorage.getItem('archaeo-community-replies')||'{}');for(const [key,rows] of Object.entries(p))if(/^[a-z]+-[0-2]$/.test(key)&&Array.isArray(rows))communityReplies[key]=rows.filter(x=>typeof x==='string').slice(-20).map(x=>x.slice(0,500));}catch{}
function communityAvailable(){return memoryCommunities.filter(c=>c.since<=Number(year()));}
function currentCommunity(){return communityAvailable().find(c=>c.id===communityId)||communityAvailable()[0];}
function openCommunity(id){if(id&&memoryCommunities.some(c=>c.id===id&&c.since<=Number(year())))communityId=id;communityThread=null;navigate({type:'community',name:'旧日社区客厅',url:'archaeo://community'});}
function communityBody(c,i){return [
 `翻到这个版面的时候，已经很晚了。${c.boards[i]}里还有几个人，帖子下面慢慢多了一层回复。我们没有什么急着要说的话，只是想在关掉网页以前，知道这边还有人。`,
 i===0?'今天翻到抽屉里的一条旧耳机线，已经缠得解不开。忽然想起以前总把一只耳机递给同桌，两个人听同一首歌，假装谁也没有注意歌词。那时候一个下午好像很长，长到可以把同一首歌听上十几遍。':i===1?'有人记得放学那条路吗？路边有一家小书店，老板总在门口看报纸。我们蹲在最下面那排书架前面，挑一本厚一点的小说，觉得只要它足够厚，周末就不会那么快结束。':'想起一个很普通的晚上。窗外下雨，家里人在看电视，手机屏幕里是一篇没有看完的故事。没有什么大事发生，后来却总想回去再过一遍。',
 '如果你也有一段差不多的记忆，就在下面留一句吧。可以是一首歌的名字、一家已经关门的小店，也可以只是一句“我还记得”。不必写得多好，能让自己想起那时候，就够了。',
 '本楼是考古浏览器原创体验帖，用来重现逛社区、翻楼层的手感，不是旧站原帖。下面的新留言只保存在你现在使用的浏览器里，其他访问者看不到。'
 ];}
function renderCommunity(){const c=currentCommunity();if(!c)return `<section class="community-room"><h1>社区的门，还没开。</h1><p>目前最早的社区体验从 1997 年开始。可以先回到 1997 年以后，再来串门。</p><button data-year="1999">回到 1999 年</button><button data-action="home">时光首页</button></section>`;communityId=c.id;const active=communityThread,key=c.id+'-'+active,replies=communityReplies[key]||[];return `<section class="community-room community-${c.tone}"><div class="community-top"><button data-action="home">考古浏览器首页</button><span>${year()} · 旧日社区客厅</span><button data-phone-lab>手机上网</button></div><header><span class="community-logo">${c.id==='mop'?'猫':c.id==='home'?'家':c.id==='tieba'?'吧':'◈'}</span><div><h1>${c.name}</h1><p>${c.intro}</p></div><aside>过客，你好。<br>这里可以慢慢说。</aside></header><nav class="community-tabs">${communityAvailable().map(x=>`<button data-community="${x.id}" class="${x.id===c.id?'selected':''}">${x.name}</button>`).join('')}</nav><div class="community-notice">原创社区体验 · 不连接旧站账号 · 新留言仅本机可见 <span>${siteLink('寻找真实历史页面',c.url)}</span></div><div class="community-breadcrumb"><button data-community="${c.id}">${c.name}</button> &gt; ${active===null?'版面首页':escapeHTML(c.boards[active])}</div>${active===null?`<div class="community-layout"><aside class="community-profile"><div class="community-avatar">${escapeHTML(playState.nickname).slice(0,1)}</div><b>${escapeHTML(playState.nickname)}</b><p>身份：时光过客<br>状态：今晚还没睡<br>签名：网速慢慢，日子长长。</p><button data-scene="friends">打开本机朋友簿</button><button data-scene="garden">去家园收菜</button><button data-memory-gallery>翻看贴图区</button></aside><main><div class="community-board-name">${c.boards.join('　 /　')}</div><table class="community-thread-table"><thead><tr><th>主题</th><th>版面</th></tr></thead><tbody>${c.topics.map((t,i)=>`<tr><td><button data-community-thread="${i}"><em>${i===0?'置顶':'主题'}</em>${escapeHTML(t)}</button><small>体验帖 · 楼主：晚风来信</small></td><td>${c.boards[i]}</td></tr>`).join('')}</tbody></table><div class="community-sticky"><strong>新来的朋友，先来这里坐坐。</strong><p>还记得你的第一个网名吗？还记得留言板里总是来踩空间的那个人吗？</p><button data-community-thread="0">进入帖子，留下一层 →</button></div>${eraAdvertMarkup('strip',1)}</main></div>`:`<article class="community-topic"><header><small>${c.boards[active]} / 原创体验帖</small><h2>${escapeHTML(c.topics[active])}</h2><span>只在本机的深夜聊天室 · 按楼层阅读</span></header><div class="forum-floor"><aside><div class="community-avatar">风</div><b>晚风来信</b><small>虚构楼主 / 创作角色</small><span>楼主</span></aside><div><header><b>第 1 楼</b><span>原创怀旧故事</span></header>${communityBody(c,active).map(p=>`<p>${escapeHTML(p)}</p>`).join('')}<footer>签名：愿你关掉网页以后，仍有好梦。</footer></div></div>${replies.map((text,i)=>`<div class="forum-floor"><aside><div class="community-avatar">我</div><b>${escapeHTML(playState.nickname)}</b><small>你的本机留言</small></aside><div><header><b>第 ${i+2} 楼</b><span>仅此浏览器可见</span></header><p>${escapeHTML(text)}</p></div></div>`).join('')}<form id="community-reply"><h3>我也来说一句</h3><label for="community-reply-text">留言内容</label><textarea id="community-reply-text" maxlength="500" required placeholder="写一句你还记得的事…"></textarea><button>发表本机留言</button><small>不会发送给旧站或其他用户。最多保留最近 20 条。</small></form></article>`}<footer class="community-footer">复刻社区的版式与互动手感，商标与历史站点名称属于各自权利人。体验内容为新创作。</footer></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-community],[data-community-thread]');if(!b)return;e.preventDefault();if(b.dataset.community)return openCommunity(b.dataset.community);const i=Number(b.dataset.communityThread);if(Number.isInteger(i)&&i>=0&&i<3){communityThread=i;navigate(current,false);}});
document.addEventListener('submit',e=>{if(e.target.id!=='community-reply')return;e.preventDefault();const c=currentCommunity(),t=$('#community-reply-text').value.trim().slice(0,500);if(!c||communityThread===null||!t)return;const key=c.id+'-'+communityThread;communityReplies[key]=[...(communityReplies[key]||[]),t].slice(-20);try{localStorage.setItem('archaeo-community-replies',JSON.stringify(communityReplies));}catch{toast('本机存储已满，本次留言只暂存');}navigate(current,false);toast('已发表本机留言，其他访问者不可见');});
